	move.w D0,-(SP)
	move.b DAT_CurrentMapPointerIndex,D0
	jsr ReleaseObjectPointer
	move.w (SP)+,D0
	btst.l #$00000000,D0 ; Is the "indoor" bit set?
	beq.b LAB_00230d7c
	moveq #$0000000f,D0 ; Always full brightness for indoor maps
	bra.w LAB_00230db8
