	moveq #$00000000,D1
	move.b (DAT_LightIntensityPerHour,PC,D0.w),D1
	jsr FUN_GetDungeonLightBuffIntensity
	add.w D1,D0 ; Add light intensity and outdoor light intensity together.
	bra.w LAB_00230db8
