PTR_ItemData:
	; ItemData *
	dc.l $00000000 ; null pointer address
	; This byte is tested to be not 0.
	; It is 1 in AM2_CPU and 0 in AM2_BLIT.
	; 
	; It looks like it controls some blitter
	; actions which use the following words.
	; 
	; In new version this is passed from the
	; loader (Ambermoon exe) and will be either
	; true (AM2_CPU style) or false (AM2_BLIT style).
DAT_BlitterSwitch:
	dc.b $ff
DAT_LoaderVersionMajor:
	dc.b $00 ; The loader (Ambermoon exe) passes this in.
DAT_LoaderVersionMinor:
	dc.w $0000 ; The loader (Ambermoon exe) passes this in.
